// Processar informações da exchange e extrair símbolos
const exchangeInfo = $input.item.json;

if (!exchangeInfo.symbols || !Array.isArray(exchangeInfo.symbols)) {
  throw new Error('Resposta inválida da API');
}

// Filtrar apenas pares USDT perpétuos ativos
const activeSymbols = exchangeInfo.symbols
  .filter(symbol => {
    return (
      symbol.status === 'TRADING' &&
      symbol.contractType === 'PERPETUAL' &&
      symbol.quoteAsset === 'USDT' &&
      symbol.symbol.endsWith('USDT')
    );
  })
  .map(symbol => ({
    symbol: symbol.symbol,
    baseAsset: symbol.baseAsset,
    quoteAsset: symbol.quoteAsset,
    pricePrecision: symbol.pricePrecision,
    quantityPrecision: symbol.quantityPrecision,
    contractType: symbol.contractType
  }));

// Retornar lista de símbolos
return {
  totalSymbols: exchangeInfo.symbols.length,
  activePerpetualsCount: activeSymbols.length,
  symbols: activeSymbols,
  timestamp: new Date().toISOString()
};

// Código corrigido para o node "Processar Funding Data"
// Processar dados de funding rate

const symbolData = $input.item.json;

// Se a resposta for um objeto direto (não array)
if (symbolData && symbolData.symbol) {
  const fundingRate = parseFloat(symbolData.lastFundingRate || 0);
  const markPrice = parseFloat(symbolData.markPrice || 0);
  const indexPrice = parseFloat(symbolData.indexPrice || 0);
  const nextFundingTime = symbolData.nextFundingTime;

  // Calcular métricas
  const fundingPercent = fundingRate * 100;
  const periodsPerDay = 4; // Funding a cada 4 horas
  const dailyRate = fundingRate * periodsPerDay;
  const monthlyRate = dailyRate * 30;
  const annualRate = dailyRate * 365;

  return {
    symbol: symbolData.symbol,
    fundingRate: fundingRate,
    fundingPercent: fundingPercent.toFixed(4),

    // Taxas calculadas
    rates: {
      hourly8: fundingPercent.toFixed(4) + '%',
      daily: (dailyRate * 100).toFixed(4) + '%',
      monthly: (monthlyRate * 100).toFixed(2) + '%',
      annual: (annualRate * 100).toFixed(2) + '%'
    },

    // Retorno em USD para $10,000
    returns10k: {
      daily: '$' + (dailyRate * 1000).toFixed(2),
      monthly: '$' + (monthlyRate * 1000).toFixed(2),
      annual: '$' + (annualRate * 1000).toFixed(2)
    },

    // Preços
    prices: {
      mark: markPrice.toFixed(2),
      index: indexPrice.toFixed(2),
      premium: ((markPrice - indexPrice) / indexPrice * 100).toFixed(4) + '%'
    },

    // Classificação
    classification:
      Math.abs(fundingPercent) > 0.1 ? 'EXTREME' :
      Math.abs(fundingPercent) > 0.05 ? 'HIGH' :
      Math.abs(fundingPercent) > 0.01 ? 'MODERATE' : 'LOW',

    direction: fundingRate > 0 ? 'POSITIVE' : 'NEGATIVE',

    strategy:
      fundingRate > 0.001 ? 'SHORT_OPPORTUNITY' :
      fundingRate < -0.001 ? 'LONG_OPPORTUNITY' : 'NEUTRAL',

    nextFundingTime: new Date(nextFundingTime).toISOString(),
    processedAt: new Date().toISOString()
  };
}

// Se não houver dados, retornar erro
return {
  symbol: $input.item.json.symbol || 'UNKNOWN',
  error: 'No funding data available',
  fundingRate: 0,
  fundingPercent: '0'
};

// Delta Neutral Funding Arbitrage Report v2.0 - ASTER Exchange
const inputData = $input.item.json;

// Configurações
const CONFIG = {
  CAPITAL: 1000, // Capital inicial em USD
  TOP_COUNT: 5,
  MIN_ANNUAL_RETURN: 20, // Mínimo 20% ao ano
  FUNDING_FREQUENCY: 6, // ASTER: 6x por dia (a cada 4 horas)
  EXCHANGE: 'ASTER',
  RISK_LEVELS: {
    EXTREME: { min: 100, label: '🔥 EXTREME' },
    HIGH: { min: 50, label: '💎 HIGH' },
    GOOD: { min: 30, label: '✅ GOOD' },
    MODERATE: { min: 20, label: '📊 MODERATE' }
  }
};

// Extração de dados válidos
function extractValidData(inputData) {
  let allItems = [];

  if (Array.isArray(inputData)) {
    allItems = inputData.flat();
  } else if (inputData && typeof inputData === 'object') {
    allItems = [inputData];
  }

  let extractedData = [];
  allItems.forEach(item => {
    if (item?.data && Array.isArray(item.data)) {
      extractedData.push(...item.data);
    } else if (item?.fundingRate !== undefined) {
      extractedData.push(item);
    }
  });

  return extractedData.filter(item => 
    item && 
    !item.error && 
    item.fundingRate !== undefined &&
    item.symbol &&
    item.fundingRate > 0 // Apenas funding positivo para delta neutro
  );
}

// Calcular métricas para delta neutro com $1,000
function calculateDeltaNeutralMetrics(item) {
  const fundingRate = parseFloat(item.fundingRate || 0);
  const fundingPercent = fundingRate * 100;

  // ASTER: Funding é pago 6x ao dia (a cada 4 horas)
  const perFundingUSD = CONFIG.CAPITAL * fundingRate; // Ganho por funding
  const dailyRate = fundingRate * CONFIG.FUNDING_FREQUENCY;
  const monthlyRate = dailyRate * 30;
  const annualRate = dailyRate * 365;

  // Calcular retornos em USD para capital de $1,000
  const dailyReturn = CONFIG.CAPITAL * dailyRate;
  const monthlyReturn = CONFIG.CAPITAL * monthlyRate;
  const annualReturn = CONFIG.CAPITAL * annualRate;

  // ROI percentual
  const monthlyROI = (monthlyReturn / CONFIG.CAPITAL) * 100;
  const annualROI = (annualReturn / CONFIG.CAPITAL) * 100;

  // Avaliar risco baseado no prêmio e retorno
  const premium = parseFloat(item.prices?.premium || '0');
  const riskScore = calculateRiskScore(annualROI, Math.abs(premium));

  return {
    fundingRate: fundingPercent.toFixed(4),
    perFunding: {
      percentage: fundingPercent.toFixed(4),
      usd: perFundingUSD.toFixed(3) // 3 casas para valores pequenos
    },
    daily: {
      rate: (dailyRate * 100).toFixed(4),
      usd: dailyReturn.toFixed(2),
      fundingCount: CONFIG.FUNDING_FREQUENCY
    },
    monthly: {
      rate: (monthlyRate * 100).toFixed(2),
      usd: monthlyReturn.toFixed(2),
      roi: monthlyROI.toFixed(2),
      fundingCount: CONFIG.FUNDING_FREQUENCY * 30
    },
    annual: {
      rate: (annualRate * 100).toFixed(2),
      usd: annualReturn.toFixed(2),
      roi: annualROI.toFixed(2),
      fundingCount: CONFIG.FUNDING_FREQUENCY * 365
    },
    riskScore,
    premium: premium.toFixed(4),
    breakeven: calculateBreakevenDays(fundingRate) // Dias para cobrir taxas
  };
}

// Calcular score de risco
function calculateRiskScore(annualROI, premiumAbs) {
  if (annualROI > 100) return CONFIG.RISK_LEVELS.EXTREME.label;
  if (annualROI > 50) return CONFIG.RISK_LEVELS.HIGH.label;
  if (annualROI > 30) return CONFIG.RISK_LEVELS.GOOD.label;
  return CONFIG.RISK_LEVELS.MODERATE.label;
}

// Calcular dias para breakeven (considerando taxas de ~0.1% de entrada/saída)
function calculateBreakevenDays(fundingRate) {
  const estimatedFees = 0.001; // 0.1% de taxas estimadas
  const dailyRate = fundingRate * CONFIG.FUNDING_FREQUENCY;
  return (estimatedFees / dailyRate).toFixed(1);
}

// Formatar oportunidade para exibição
function formatOpportunity(item, index) {
  const metrics = calculateDeltaNeutralMetrics(item);
  const nextFunding = new Date(item.nextFundingTime);
  const hoursUntilNext = Math.max(0, (nextFunding - new Date()) / (1000 * 60 * 60));

  // Calcular alocação proporcional do capital
  const allocationPerPair = (CONFIG.CAPITAL / CONFIG.TOP_COUNT).toFixed(2);

  return {
    rank: index + 1,
    symbol: item.symbol.replace('USDT', ''),
    markPrice: item.prices.mark,
    allocation: allocationPerPair,
    fundingRate: metrics.fundingRate + '%',
    premium: metrics.premium + '%',
    perFunding: {
      percentage: metrics.perFunding.percentage + '%',
      usd: '$' + metrics.perFunding.usd
    },
    returns: {
      daily: {
        percentage: metrics.daily.rate + '%',
        usd: '$' + metrics.daily.usd,
        payments: metrics.daily.fundingCount
      },
      monthly: {
        percentage: metrics.monthly.rate + '%',
        usd: '$' + metrics.monthly.usd,
        roi: metrics.monthly.roi + '%',
        payments: metrics.monthly.fundingCount
      },
      annual: {
        percentage: metrics.annual.rate + '%',
        usd: '$' + metrics.annual.usd,
        roi: metrics.annual.roi + '%',
        payments: metrics.annual.fundingCount
      }
    },
    risk: metrics.riskScore,
    breakeven: metrics.breakeven,
    nextFunding: {
      time: nextFunding.toLocaleString('pt-BR'),
      hoursRemaining: hoursUntilNext.toFixed(1)
    },
    strategy: {
      spot: 'LONG (Comprar)',
      futures: 'SHORT (Vender)',
      result: 'Recebe Funding 6x/dia'
    }
  };
}

// Gerar mensagem de alerta formatada
function generateAlertMessage(opportunities) {
  const lines = [
    `🎯 **TOP 5 DELTA NEUTRAL - ASTER EXCHANGE**`,
    `━━━━━━━━━━━━━━━━━━━━━━━━`,
    `📍 Exchange: ${CONFIG.EXCHANGE}`,
    `⏰ ${new Date().toLocaleString('pt-BR')}`,
    `💰 Capital: $${CONFIG.CAPITAL.toFixed(2)}`,
    `⚡ Funding: A cada 4 horas (6x/dia)`,
    ``,
    `📊 **ESTRATÉGIA DELTA NEUTRO**`,
    `├─ Capital por par: $${(CONFIG.CAPITAL / CONFIG.TOP_COUNT).toFixed(2)}`,
    `├─ Comprar SPOT (posição LONG)`,
    `├─ Vender FUTURES (posição SHORT)`,
    `└─ Receber funding 6x ao dia`,
    ``
  ];

  opportunities.forEach(opp => {
    const medal = opp.rank === 1 ? '🥇' : 
                  opp.rank === 2 ? '🥈' : 
                  opp.rank === 3 ? '🥉' : 
                  `${opp.rank}.`;

    lines.push(`${medal} **${opp.symbol}** ${opp.risk}`);
    lines.push(`├─ Funding/4h: ${opp.perFunding.percentage} (${opp.perFunding.usd})`);
    lines.push(`├─ Diário: ${opp.returns.daily.percentage} (${opp.returns.daily.usd})`);
    lines.push(`│  └─ ${opp.returns.daily.payments} pagamentos`);
    lines.push(`├─ Mensal: ${opp.returns.monthly.percentage} (${opp.returns.monthly.usd})`);
    lines.push(`│  └─ ROI: ${opp.returns.monthly.roi} | ${opp.returns.monthly.payments} pagamentos`);
    lines.push(`├─ Anual: ${opp.returns.annual.percentage} (${opp.returns.annual.usd})`);
    lines.push(`│  └─ ROI: ${opp.returns.annual.roi} | ${opp.returns.annual.payments} pagamentos`);
    lines.push(`├─ Prêmio: ${opp.premium}`);
    lines.push(`├─ Preço: $${opp.markPrice}`);
    lines.push(`├─ Breakeven: ${opp.breakeven} dias`);
    lines.push(`└─ Próximo: ${opp.nextFunding.hoursRemaining}h`);
    lines.push(``);
  });

  // Resumo executivo com capital de $1,000
  const totalDailyReturn = opportunities.reduce((sum, opp) => 
    sum + (parseFloat(opp.returns.daily.usd.replace('$', '')) / CONFIG.TOP_COUNT), 0
  );
  const totalMonthlyReturn = opportunities.reduce((sum, opp) => 
    sum + (parseFloat(opp.returns.monthly.usd.replace('$', '')) / CONFIG.TOP_COUNT), 0
  );
  const totalAnnualReturn = opportunities.reduce((sum, opp) => 
    sum + (parseFloat(opp.returns.annual.usd.replace('$', '')) / CONFIG.TOP_COUNT), 0
  );

  const monthlyROI = (totalMonthlyReturn / CONFIG.CAPITAL) * 100;
  const annualROI = (totalAnnualReturn / CONFIG.CAPITAL) * 100;

  lines.push(`💎 **RESUMO DO PORTFÓLIO**`);
  lines.push(`├─ Capital Total: $${CONFIG.CAPITAL.toFixed(2)}`);
  lines.push(`├─ Retorno Diário: $${totalDailyReturn.toFixed(2)} (${(totalDailyReturn/CONFIG.CAPITAL*100).toFixed(2)}%)`);
  lines.push(`├─ Retorno Mensal: $${totalMonthlyReturn.toFixed(2)} (${monthlyROI.toFixed(2)}% ROI)`);
  lines.push(`├─ Retorno Anual: $${totalAnnualReturn.toFixed(2)} (${annualROI.toFixed(2)}% ROI)`);
  lines.push(`└─ Tempo médio breakeven: ${(opportunities.reduce((sum, opp) => 
    sum + parseFloat(opp.breakeven), 0) / opportunities.length).toFixed(1)} dias`);
  lines.push(``);
  lines.push(`📈 **PROJEÇÃO DE CRESCIMENTO**`);
  lines.push(`├─ Mês 1: $${(CONFIG.CAPITAL + totalMonthlyReturn).toFixed(2)}`);
  lines.push(`├─ Mês 3: $${(CONFIG.CAPITAL * Math.pow(1 + monthlyROI/100, 3)).toFixed(2)}`);
  lines.push(`├─ Mês 6: $${(CONFIG.CAPITAL * Math.pow(1 + monthlyROI/100, 6)).toFixed(2)}`);
  lines.push(`└─ Ano 1: $${(CONFIG.CAPITAL * Math.pow(1 + monthlyROI/100, 12)).toFixed(2)}`);
  lines.push(``);
  lines.push(`⚠️ **GESTÃO DE RISCO**`);
  lines.push(`• Usar apenas ${(100/CONFIG.TOP_COUNT).toFixed(0)}% do capital por par`);
  lines.push(`• Manter margem de 150% para evitar liquidação`);
  lines.push(`• Rebalancear quando funding < 0.01%/4h`);
  lines.push(`• Considerar taxas de ~0.05% por trade`);
  lines.push(`• Monitorar descasamento spot/futures`);

  return lines.join('\n');
}

// Executar análise
try {
  const validItems = extractValidData(inputData);

  if (validItems.length === 0) {
    return {
      success: false,
      error: 'Nenhum par com funding rate positivo encontrado',
      timestamp: new Date().toISOString()
    };
  }

  // Filtrar apenas funding positivos significativos
  const positiveItems = validItems.filter(item => {
    const metrics = calculateDeltaNeutralMetrics(item);
    return parseFloat(metrics.annual.roi) >= CONFIG.MIN_ANNUAL_RETURN;
  });

  // Ordenar por retorno anual
  const sortedItems = positiveItems.sort((a, b) => {
    const aMetrics = calculateDeltaNeutralMetrics(a);
    const bMetrics = calculateDeltaNeutralMetrics(b);
    return parseFloat(bMetrics.annual.roi) - parseFloat(aMetrics.annual.roi);
  });

  // Pegar top 5
  const top5 = sortedItems.slice(0, CONFIG.TOP_COUNT);
  const opportunities = top5.map((item, index) => formatOpportunity(item, index));

  // Calcular métricas agregadas do portfólio
  const portfolioMetrics = {
    capitalPerPair: (CONFIG.CAPITAL / CONFIG.TOP_COUNT).toFixed(2),
    avgDailyReturn: (opportunities.reduce((sum, opp) => 
      sum + (parseFloat(opp.returns.daily.usd.replace('$', '')) / CONFIG.TOP_COUNT), 0)
    ).toFixed(2),
    avgMonthlyReturn: (opportunities.reduce((sum, opp) => 
      sum + (parseFloat(opp.returns.monthly.usd.replace('$', '')) / CONFIG.TOP_COUNT), 0)
    ).toFixed(2),
    avgAnnualReturn: (opportunities.reduce((sum, opp) => 
      sum + (parseFloat(opp.returns.annual.usd.replace('$', '')) / CONFIG.TOP_COUNT), 0)
    ).toFixed(2),
    bestPair: opportunities[0]?.symbol || 'N/A',
    bestAnnualROI: opportunities[0]?.returns.annual.roi || '0%',
    totalFundingPerDay: CONFIG.FUNDING_FREQUENCY,
    totalFundingPerMonth: CONFIG.FUNDING_FREQUENCY * 30,
    totalFundingPerYear: CONFIG.FUNDING_FREQUENCY * 365
  };

  return {
    success: true,
    timestamp: new Date().toISOString(),
    exchange: CONFIG.EXCHANGE,
    strategy: 'DELTA_NEUTRAL_FUNDING_ARBITRAGE',
    capital: `$${CONFIG.CAPITAL}`,
    fundingFrequency: '4 horas (6x ao dia)',
    summary: {
      totalOpportunities: positiveItems.length,
      topCount: opportunities.length,
      portfolio: portfolioMetrics
    },
    opportunities,
    executionSteps: [
      `1. Capital: $${CONFIG.CAPITAL} dividido em ${CONFIG.TOP_COUNT} pares ($${portfolioMetrics.capitalPerPair} cada)`,
      '2. Para cada par: comprar no mercado SPOT',
      '3. Simultaneamente: vender a mesma quantidade em FUTURES perpétuos',
      '4. Receber funding a cada 4 horas (6x ao dia)',
      '5. Monitorar funding rate - se ficar negativo, fechar posição',
      '6. Rebalancear semanalmente baseado em performance'
    ],
    alertMessage: generateAlertMessage(opportunities),
    disclaimer: 'Estratégia assume execução perfeita. Considere: taxas (0.05-0.1%), slippage, margem de manutenção (5-10%), e volatilidade do mercado.'
  };

} catch (error) {
  return {
    success: false,
    error: `Erro na análise: ${error.message}`,
    timestamp: new Date().toISOString()
  };
}
